import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    # Count opponent's defections so far
    opp_defections = 0
    my_defections = 0
    for (me, opp) in history:
        if opp == 'D':
            opp_defections += 1
        if me == 'D':
            my_defections += 1

    # If opponent has never defected, cooperate.
    if opp_defections == 0:
        return 'C'

    # If opponent defected last round, retaliate.
    if history[-1][1] == 'D':
        # Tit-for-tat style: defect back, but occasionally cooperate to avoid lock-in.
        # Use a small deterministic-ish probability based on rng.
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Opponent's last action was C, but they have defected before.
    # Estimate their defection rate.
    rate = opp_defections / n

    # If defection rate is low, cooperate more.
    if rate < 0.15:
        return 'C'
    # If defection rate is moderate, mix.
    if rate < 0.4:
        if rng.random() < 0.7:
            return 'C'
        return 'D'
    # If opponent is frequently defecting, defect more often.
    if rng.random() < 0.35:
        return 'C'
    return 'D'

